30	
31	/**
32	 * 批次拆分血缘与祖先召回拦截测试：拆分主流程、失败回滚、commandKey 幂等、
33	 * 祖先/后代查询、祖先召回对后代的拦截与可用性排除、无关血缘树隔离、并发裁决。
34	 */
35	@SpringBootTest
36	@AutoConfigureMockMvc
37	class BatchSplitLineageTest {
38	
39	    @Autowired
40	    private MockMvc mockMvc;
41	    @Autowired
42	    private ObjectMapper objectMapper;
43	    @Autowired
44	    private JdbcTemplate jdbc;
45	
46	    @BeforeEach
47	    void cleanTables() {
48	        jdbc.update("DELETE FROM command_log");
49	        jdbc.update("DELETE FROM approval");
50	        jdbc.update("DELETE FROM recall");
51	        jdbc.update("DELETE FROM test_result");
52	        jdbc.update("DELETE FROM batch_required_test");
53	        jdbc.update("DELETE FROM batch_lineage");
54	        jdbc.update("DELETE FROM batch");
55	    }
56	
57	    // ---------- 拆分主流程 ----------
58	
59	    @Test
60	    void happySplit_parentBecomesSplit_childrenInheritAndStartQuarantined() throws Exception {
61	        String parent = "BK-SP-P-" + unique();
62	        createBatch(parent, List.of("外观", "含量"), 201);
63	        releaseBatch(parent, "insp-1");
64	
65	        List<String> childKeys = List.of("BK-SP-C1-" + unique(), "BK-SP-C2-" + unique(),
66	                "BK-SP-C3-" + unique());
67	        MvcResult result = split(parent, "CK-SPLIT-1",
68	                childKeys.stream().map(k -> new String[]{k, "LOT-" + k.substring(k.length() - 4)})
69	                        .toList(), 201);
70	
71	        JsonNode body = objectMapper.readTree(result.getResponse().getContentAsString());
72	        assertEquals(parent, body.path("parentBatchKey").asText());
73	        assertEquals("SPLIT", body.path("parentStatus").asText());
74	        assertEquals(3, body.path("children").size());
75	        for (int i = 0; i < 3; i++) {
