            MvcResult r3 = submitSeq(batchKey, "CK-S3", 3, "GOOD", "sampler-b", 201);
            assertEquals("CONTINUE", objectMapper.readTree(r3.getResponse().getContentAsString())
                    .path("conclusion").asText());
            assertEquals(3, seqRowCount(batchKey));
        }
    }

