        approve(child1, "qa-2", "QUALITY", "CK-CQ", 422);
        assertEquals(1, seqRowCount(child1), "祖先召回后子批序贯前缀不得改写");
        assertEquals("QUARANTINED", currentStatus(child1), "后代自身状态不被祖先召回改写");
    }

